private void xrLabel9_SummaryGetResult(object sender, DevExpress.XtraReports.UI.SummaryGetResultEventArgs e) {
            if (sasia != 0)
                e.Result = shuma / sasia;
            else e.Result = shuma;
            e.Handled = true;
}

private void xrLabel9_SummaryReset(object sender, System.EventArgs e) {
            shuma = 0;
            sasia = 0;
}



