                   xrLabel1.NavigateUrl = "javascript:window.myFaqeCelje.hapFaqeNeTabTeRi('RaportiShpejte.aspx?scopeID="+parametraRaporti.ScopeID+"&guidString=" + parametraRaporti.GuidString+ "&idraporti=" + parametraRaporti.IdSubRaporti+ "&filterKartela=" + GetCurrentColumnValue("KODI") + "&printo=0&Sesioni=true')";
