int row = 0;

private void GroupHeader1_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e){
            if (row % 2 == 0)
                GroupHeader1.Styles.Style = (DevExpress.XtraReports.UI.XRControlStyle)StyleSheet["PermbajtjaRaportEven"];
            else
                GroupHeader1.Styles.Style = (DevExpress.XtraReports.UI.XRControlStyle)StyleSheet["PermbajtjaRaportOdd"];
            row++;
}


